(() => {
 const key='raylio-service-drafts-v1';const $=id=>document.getElementById(id);
 let data=RaylabServices.validate(window.RAYLAB_SERVICES),editing=null,image='',imageBusy=false;
 let storageWarning='';try{const saved=localStorage.getItem(key);if(saved)data=RaylabServices.validate(JSON.parse(saved))}catch{storageWarning='No pudimos recuperar los borradores de este navegador. Puedes importar un respaldo.'}
 const node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el};
 function status(text,error=false){$('admin-status').textContent=text;$('admin-status').classList.toggle('error',error)}
 function persist(){try{localStorage.setItem(key,JSON.stringify(data));status('Borrador guardado en este navegador. La web publicada todavía no cambia.');return true}catch{status('El navegador no pudo guardar el borrador. Descarga un respaldo ahora para conservar tus cambios.',true);return false}}
 function heading(){ $('catalog-title').value=data.heading;$('catalog-description').value=data.description; }
 function renderList(){const list=$('service-list');list.replaceChildren();$('service-count').textContent=`${data.services.length} / 30`;if(!data.services.length)list.append(node('p','empty-list','Tu catálogo está vacío. Agrega tu primer servicio.'));data.services.forEach((s,index)=>{const card=node('article','admin-service'),top=node('div','admin-service-top');top.append(node('h3','',s.title),node('span',`visibility-badge ${s.published?'':'draft'}`,s.published?'Visible al exportar':'Borrador'));card.append(top,node('p','',s.description));const actions=node('div','row-actions');function action(label,fn,disabled=false,cls=''){const b=node('button',cls,label);b.type='button';b.disabled=disabled;b.addEventListener('click',fn);actions.append(b)}action('Editar',()=>edit(s.id));action('↑',()=>move(index,-1),index===0);actions.lastChild.setAttribute('aria-label',`Subir ${s.title}`);action('↓',()=>move(index,1),index===data.services.length-1);actions.lastChild.setAttribute('aria-label',`Bajar ${s.title}`);action(s.published?'Ocultar':'Mostrar',()=>{s.published=!s.published;if(editing===s.id)$('service-published').checked=s.published;persist();renderList();preview()});action('Eliminar',()=>{if(!confirm(`¿Eliminar «${s.title}» del borrador?`))return;data.services=data.services.filter(item=>item.id!==s.id);if(editing===s.id)reset();persist();renderList()},false,'delete');card.append(actions);list.append(card)})}
 function move(index,delta){[data.services[index],data.services[index+delta]]=[data.services[index+delta],data.services[index]];persist();renderList()}
 function readEditor(){return {id:editing||`service-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,title:$('service-title').value.trim(),category:$('service-category').value.trim(),description:$('service-description').value.trim(),features:$('service-features').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8),price:$('service-price').value.trim(),published:$('service-published').checked,image}}
 function preview(){const s=readEditor();const box=$('live-preview');box.replaceChildren();const card=node('article','service custom-service');if(image){const img=node('img','service-photo');img.src=image;img.alt=s.title||'Imagen de tu servicio';card.append(img)}const top=node('div','service-topline');top.append(node('span','service-category',s.category||'TU CATEGORÍA'),node('span','service-index','01'));card.append(top,node('h3','',s.title||'El nombre de tu servicio'),node('p','',s.description||'Explica qué ofreces y cómo ayudas al negocio de tu cliente.'));if(s.features.length){const ul=node('ul','');s.features.forEach(f=>ul.append(node('li','',f)));card.append(ul)}if(s.price)card.append(node('div','service-price',s.price));card.append(node('div','preview-cta','Hablemos de este servicio ↗'));box.append(card);$('image-wrap').hidden=!image;if(image)$('image-preview').src=image;else $('image-preview').removeAttribute('src')}
 function reset(){editing=null;image='';$('service-form').reset();$('service-published').checked=true;$('editor-title').textContent='Nuevo servicio';preview()}
 function edit(id){const s=data.services.find(s=>s.id===id);if(!s)return;editing=s.id;image=s.image;$('service-title').value=s.title;$('service-category').value=s.category;$('service-description').value=s.description;$('service-features').value=s.features.join('\n');$('service-price').value=s.price;$('service-published').checked=s.published;$('service-image').value='';$('editor-title').textContent='Editar servicio';preview();$('service-title').focus()}
 $('new-service').addEventListener('click',()=>{reset();$('service-title').focus()});$('cancel-edit').addEventListener('click',reset);$('service-form').addEventListener('input',preview);
 $('save-heading').addEventListener('click',()=>{data=RaylabServices.validate({...data,heading:$('catalog-title').value,description:$('catalog-description').value});heading();persist()});
 $('service-form').addEventListener('submit',event=>{event.preventDefault();if(imageBusy){status('Espera a que termine de cargar la imagen.',true);return}try{const service=RaylabServices.validate({services:[readEditor()]}).services[0];if(editing)data.services=data.services.map(s=>s.id===editing?service:s);else{if(data.services.length>=30)throw Error('Puedes agregar hasta 30 servicios.');data.services.push(service)}persist();renderList();reset()}catch(error){status(error.message,true)}});
 $('remove-image').addEventListener('click',()=>{image='';$('service-image').value='';preview()});
 $('service-image').addEventListener('change',async()=>{const file=$('service-image').files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){status('Elige una imagen PNG, JPG o WebP de hasta 8 MB.',true);$('service-image').value='';return}imageBusy=true;const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('No pudimos leer esta imagen.'));img.src=url});const scale=Math.min(1,1200/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/webp',.8);if(result.length>1000000)throw Error('La imagen sigue siendo muy grande. Usa una imagen más pequeña.');image=result;preview();status('Imagen preparada. Guarda el servicio para conservarla.')}catch(error){status(error.message,true)}finally{imageBusy=false;URL.revokeObjectURL(url)}});
 function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 function published(){return RaylabServices.validate({...data,services:data.services.filter(s=>s.published)})}
 function pending(){return confirm('Se exportarán los servicios guardados. Si estás editando uno, asegúrate de haber pulsado «Guardar servicio». ¿Continuar?')}
 $('export-site').textContent='Descargar catálogo ZIP';
 $('export-site').addEventListener('click',()=>{if(!pending())return;download(RaylabServices.catalogZip(published()),'raylab-catalogo.zip','application/zip');status('Catálogo descargado. Extrae services-data.js del ZIP, reemplázalo en la carpeta de tu web y vuelve a publicarla.')});
 $('backup').addEventListener('click',()=>{download(JSON.stringify(data,null,2),'raylab-servicios-respaldo.json','application/json');status('Respaldo descargado con todos tus servicios y borradores guardados.')});
 $('import-file').addEventListener('change',async()=>{const file=$('import-file').files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('El respaldo supera los 20 MB.');const incoming=RaylabServices.validate(JSON.parse(await file.text()));if(!confirm('¿Reemplazar los borradores actuales por este respaldo?'))return;data=incoming;heading();reset();renderList();persist()}catch(error){status(error.message,true)}finally{$('import-file').value=''}});
 $('write-folder').addEventListener('click',async()=>{if(!('showDirectoryPicker'in window)){status('Este navegador no permite guardar directamente en una carpeta. Usa «Descargar catálogo ZIP» y reemplaza el archivo manualmente.',true);return}if(!pending())return;try{const folder=await window.showDirectoryPicker({mode:'readwrite'});try{await folder.getFileHandle('index.html')}catch{throw Error('Elige la carpeta dist de Raylab: debe contener index.html.')}const scripts=await folder.getDirectoryHandle('js',{create:true});const file=await scripts.getFileHandle('services-data.js',{create:true});const writable=await file.createWritable();await writable.write(RaylabServices.serialize(published()));await writable.close();status('Servicios guardados en tu carpeta web. Recarga index.html para verlos. Para internet, vuelve a subir la carpeta a Cloudflare.')}catch(error){if(error.name!=='AbortError')status(error.message,true)}});
 heading();renderList();reset();if(storageWarning)status(storageWarning,true);
})();
